-- iJob MySQL 8 baseline. IDs are generated by the application Snowflake generator.

CREATE TABLE ifj_calendar (
    id BIGINT NOT NULL,
    name VARCHAR(128) NOT NULL,
    workdays_mask INT NOT NULL,
    description VARCHAR(500) NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_calendar PRIMARY KEY (id),
    CONSTRAINT uk_ifj_calendar_name UNIQUE (name)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_calendar_exception (
    id BIGINT NOT NULL,
    calendar_id BIGINT NOT NULL,
    date DATE NOT NULL,
    type VARCHAR(32) NOT NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_calendar_exception PRIMARY KEY (id),
    CONSTRAINT uk_ifj_calendar_exception_date UNIQUE (calendar_id, date),
    CONSTRAINT fk_ifj_calendar_exception_calendar
        FOREIGN KEY (calendar_id) REFERENCES ifj_calendar (id) ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_task (
    id BIGINT NOT NULL,
    name VARCHAR(128) NOT NULL,
    plugin_type VARCHAR(32) NOT NULL,
    plugin_config LONGTEXT NOT NULL,
    retry_times INT NOT NULL DEFAULT 0,
    retry_interval INT NOT NULL DEFAULT 0,
    timeout INT NULL,
    enabled TINYINT(1) NOT NULL DEFAULT 1,
    description VARCHAR(500) NULL,
    concurrency_type VARCHAR(32) NULL,
    lock_key VARCHAR(255) NULL,
    max_concurrency INT NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_task PRIMARY KEY (id),
    INDEX idx_ifj_task_enabled_plugin_type (enabled, plugin_type)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_job (
    id BIGINT NOT NULL,
    name VARCHAR(128) NOT NULL,
    timeout INT NULL,
    enabled TINYINT(1) NOT NULL DEFAULT 1,
    description VARCHAR(500) NULL,
    concurrency_type VARCHAR(32) NULL,
    lock_key VARCHAR(255) NULL,
    max_concurrency INT NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_job PRIMARY KEY (id),
    INDEX idx_ifj_job_enabled (enabled)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_job_node (
    id BIGINT NOT NULL,
    name VARCHAR(128) NOT NULL,
    job_id BIGINT NOT NULL,
    node_type VARCHAR(32) NOT NULL,
    ref_id BIGINT NOT NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_job_node PRIMARY KEY (id),
    CONSTRAINT fk_ifj_job_node_job
        FOREIGN KEY (job_id) REFERENCES ifj_job (id) ON DELETE CASCADE,
    INDEX idx_ifj_job_node_job_id (job_id),
    INDEX idx_ifj_job_node_ref (node_type, ref_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_job_edge (
    id BIGINT NOT NULL,
    job_id BIGINT NOT NULL,
    from_node_id BIGINT NOT NULL,
    to_node_id BIGINT NOT NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_job_edge PRIMARY KEY (id),
    CONSTRAINT uk_ifj_job_edge_path UNIQUE (job_id, from_node_id, to_node_id),
    CONSTRAINT fk_ifj_job_edge_job
        FOREIGN KEY (job_id) REFERENCES ifj_job (id) ON DELETE CASCADE,
    CONSTRAINT fk_ifj_job_edge_from_node
        FOREIGN KEY (from_node_id) REFERENCES ifj_job_node (id) ON DELETE CASCADE,
    CONSTRAINT fk_ifj_job_edge_to_node
        FOREIGN KEY (to_node_id) REFERENCES ifj_job_node (id) ON DELETE CASCADE,
    INDEX idx_ifj_job_edge_to_node_id (to_node_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_job_node_policy (
    id BIGINT NOT NULL,
    node_id BIGINT NOT NULL,
    fail_strategy VARCHAR(32) NOT NULL,
    execute_condition VARCHAR(32) NOT NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_job_node_policy PRIMARY KEY (id),
    CONSTRAINT uk_ifj_job_node_policy_node_id UNIQUE (node_id),
    CONSTRAINT fk_ifj_job_node_policy_node
        FOREIGN KEY (node_id) REFERENCES ifj_job_node (id) ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_schedule (
    id BIGINT NOT NULL,
    target_type VARCHAR(32) NOT NULL,
    target_id BIGINT NOT NULL,
    schedule_type VARCHAR(32) NOT NULL,
    cron_expr VARCHAR(128) NULL,
    interval_sec INT NULL,
    calendar_id BIGINT NULL,
    start_time DATETIME(3) NULL,
    end_time DATETIME(3) NULL,
    enabled TINYINT(1) NOT NULL DEFAULT 1,
    last_fire_time DATETIME(3) NULL,
    next_fire_time DATETIME(3) NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_schedule PRIMARY KEY (id),
    CONSTRAINT fk_ifj_schedule_calendar
        FOREIGN KEY (calendar_id) REFERENCES ifj_calendar (id) ON DELETE SET NULL,
    INDEX idx_ifj_schedule_target (target_type, target_id),
    INDEX idx_ifj_schedule_fire (enabled, next_fire_time)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_concurrency_policy (
    id BIGINT NOT NULL,
    target_id BIGINT NOT NULL,
    target_type VARCHAR(32) NOT NULL,
    concurrency_type VARCHAR(32) NOT NULL,
    lock_key VARCHAR(255) NULL,
    max_concurrency INT NULL,
    enabled TINYINT(1) NOT NULL DEFAULT 1,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_concurrency_policy PRIMARY KEY (id),
    CONSTRAINT uk_ifj_concurrency_policy_target UNIQUE (target_type, target_id),
    INDEX idx_ifj_concurrency_policy_lock_key (lock_key)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_event_binding (
    id BIGINT NOT NULL,
    target_type VARCHAR(32) NOT NULL,
    target_id BIGINT NOT NULL,
    event_code VARCHAR(128) NOT NULL,
    enabled TINYINT(1) NOT NULL DEFAULT 1,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_event_binding PRIMARY KEY (id),
    CONSTRAINT uk_ifj_event_binding_target UNIQUE (target_type, target_id, event_code),
    INDEX idx_ifj_event_binding_event (event_code, enabled)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_notify_config (
    id BIGINT NOT NULL,
    name VARCHAR(128) NOT NULL,
    type VARCHAR(32) NOT NULL,
    config LONGTEXT NOT NULL,
    enabled TINYINT(1) NOT NULL DEFAULT 1,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_notify_config PRIMARY KEY (id),
    INDEX idx_ifj_notify_config_type_enabled (type, enabled)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_notify_binding (
    id BIGINT NOT NULL,
    target_type VARCHAR(32) NOT NULL,
    target_id BIGINT NOT NULL,
    notify_config_id BIGINT NOT NULL,
    notify_policy VARCHAR(32) NOT NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_notify_binding PRIMARY KEY (id),
    CONSTRAINT uk_ifj_notify_binding_target
        UNIQUE (target_type, target_id, notify_config_id),
    CONSTRAINT fk_ifj_notify_binding_config
        FOREIGN KEY (notify_config_id) REFERENCES ifj_notify_config (id) ON DELETE CASCADE,
    INDEX idx_ifj_notify_binding_target (target_type, target_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_resource (
    id BIGINT NOT NULL,
    code VARCHAR(128) NOT NULL,
    name VARCHAR(128) NOT NULL,
    type VARCHAR(32) NOT NULL,
    config LONGTEXT NOT NULL,
    enabled TINYINT(1) NOT NULL DEFAULT 1,
    description VARCHAR(500) NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_resource PRIMARY KEY (id),
    CONSTRAINT uk_ifj_resource_code UNIQUE (code),
    INDEX idx_ifj_resource_type_enabled (type, enabled)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_trigger (
    id BIGINT NOT NULL,
    schedule_id BIGINT NULL,
    target_type VARCHAR(32) NOT NULL,
    target_id BIGINT NOT NULL,
    trigger_type VARCHAR(32) NOT NULL,
    event_code VARCHAR(128) NULL,
    status VARCHAR(32) NOT NULL,
    trigger_time DATETIME(3) NOT NULL,
    message TEXT NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_trigger PRIMARY KEY (id),
    CONSTRAINT fk_ifj_trigger_schedule
        FOREIGN KEY (schedule_id) REFERENCES ifj_schedule (id) ON DELETE SET NULL,
    INDEX idx_ifj_trigger_status_time (status, trigger_time),
    INDEX idx_ifj_trigger_target (target_type, target_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_instance (
    id BIGINT NOT NULL,
    node_id BIGINT NULL,
    parent_instance_id BIGINT NULL,
    root_instance_id BIGINT NULL,
    target_type VARCHAR(32) NOT NULL,
    target_id BIGINT NOT NULL,
    trigger_type VARCHAR(32) NULL,
    trigger_id BIGINT NULL,
    status VARCHAR(32) NOT NULL,
    progress INT NOT NULL DEFAULT 0,
    retry_count INT NOT NULL DEFAULT 0,
    start_time DATETIME(3) NULL,
    end_time DATETIME(3) NULL,
    message TEXT NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_instance PRIMARY KEY (id),
    CONSTRAINT uk_ifj_instance_parent_node UNIQUE (parent_instance_id, node_id),
    CONSTRAINT fk_ifj_instance_node
        FOREIGN KEY (node_id) REFERENCES ifj_job_node (id) ON DELETE SET NULL,
    CONSTRAINT fk_ifj_instance_parent
        FOREIGN KEY (parent_instance_id) REFERENCES ifj_instance (id) ON DELETE CASCADE,
    CONSTRAINT fk_ifj_instance_root
        FOREIGN KEY (root_instance_id) REFERENCES ifj_instance (id) ON DELETE CASCADE,
    CONSTRAINT fk_ifj_instance_trigger
        FOREIGN KEY (trigger_id) REFERENCES ifj_trigger (id) ON DELETE SET NULL,
    INDEX idx_ifj_instance_root_status (root_instance_id, status),
    INDEX idx_ifj_instance_target (target_type, target_id),
    INDEX idx_ifj_instance_trigger_id (trigger_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

CREATE TABLE ifj_instance_log (
    id BIGINT NOT NULL,
    instance_id BIGINT NOT NULL,
    log_time DATETIME(3) NOT NULL,
    level VARCHAR(16) NOT NULL,
    content LONGTEXT NOT NULL,
    CONSTRAINT pk_ifj_instance_log PRIMARY KEY (id),
    CONSTRAINT fk_ifj_instance_log_instance
        FOREIGN KEY (instance_id) REFERENCES ifj_instance (id) ON DELETE CASCADE,
    INDEX idx_ifj_instance_log_instance_time (instance_id, log_time)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;
